import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.8tqBsFWt.js";const m=JSON.parse('{"title":"Month-end margin review","description":"","frontmatter":{},"headers":[],"relativePath":"playbook/month-end-margin-review.md","filePath":"playbook/month-end-margin-review.md"}'),r={name:"playbook/month-end-margin-review.md"};function i(l,e,s,h,c,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="month-end-margin-review" tabindex="-1">Month-end margin review <a class="header-anchor" href="#month-end-margin-review" aria-label="Permalink to &quot;Month-end margin review&quot;">​</a></h1><p><strong>Cadence</strong>: Monthly · <strong>Who</strong>: Owners</p><h2 id="situation" tabindex="-1">Situation <a class="header-anchor" href="#situation" aria-label="Permalink to &quot;Situation&quot;">​</a></h2><p>End of the month. You want the P&amp;L picture — revenue, cost, margin by project — before you close the books. This is the read that answers <em>how did we actually do?</em> without needing a bookkeeper or a spreadsheet marathon.</p><h2 id="in-the-console" tabindex="-1">In the console <a class="header-anchor" href="#in-the-console" aria-label="Permalink to &quot;In the console&quot;">​</a></h2><p>Open <strong>Reports</strong> (<code>/console/reports</code>) → the <strong>Monthly P&amp;L</strong> tab. Revenue, cost, profit, margin and LER by month, chart above the table. The <strong>Segmentation</strong> tab breaks the same numbers down by customer or by discipline; <strong>Export</strong> pulls the rows to CSV.</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>A per-project table:</p><p>| Project | Client | Type | Revenue | Cost | Margin | Margin % |</p><p>Plus rollups:</p><ul><li><strong>By project type</strong> — retainer, T&amp;M, fixed price, agile, pro bono, internal</li><li><strong>By client</strong> — total revenue, total cost, total margin per client</li><li><strong>Totals</strong> — the line you&#39;ll carry into your management accounts</li></ul><p>And alerts:</p><ul><li>Projects with unusual variance vs. the previous month called out</li><li>Projects that moved from on-track to over-budget in the month</li><li>Vendor liabilities that closed in the month, with their effect on margin</li></ul><p>Cost respects the P&amp;L rule: where a vendor liability exists, the agreed amount is used; otherwise hours × the rate effective on each time entry&#39;s date.</p><h2 id="who-can-run-it" tabindex="-1">Who can run it <a class="header-anchor" href="#who-can-run-it" aria-label="Permalink to &quot;Who can run it&quot;">​</a></h2><p>Owners only. Contains dollar amounts not visible to other roles.</p><h2 id="related-plays" tabindex="-1">Related plays <a class="header-anchor" href="#related-plays" aria-label="Permalink to &quot;Related plays&quot;">​</a></h2><ul><li><a href="./retainer-burn-check.html">Retainer burn check</a> — the weekly signal that feeds this monthly read</li><li><a href="./client-summary.html">Client summary for a review meeting</a> — the client-facing version</li></ul>',18)])])}const p=t(r,[["render",i]]);export{m as __pageData,p as default};
